// Published evidence copy: synthetic role email redacted; private original used during execution.
import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func testFixedOwnNotificationsAndKeyboardPhysicalSend() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Inbox, tab, 4 of 5");tap(app,"Notifications");let cancelled=app.staticTexts["Meal cancelled"];XCTAssertTrue(cancelled.waitForExistence(timeout:15),app.debugDescription);let unread=app.buttons["Mark as read"].firstMatch;XCTAssertTrue(unread.waitForExistence(timeout:10));XCTAssertTrue(unread.isHittable);unread.tap();XCTAssertTrue(app.staticTexts["Read"].firstMatch.waitForExistence(timeout:12),app.debugDescription);let notice=XCTAttachment(screenshot:app.screenshot());notice.name="native106-own-cancellation-notice-read";notice.lifetime = .keepAlways;add(notice);print("QA_NATIVE106_NOTIFICATION_LIST_MARK_READ\n"+app.debugDescription);
 app.terminate();app.launch();tap(app,"Inbox, tab, 4 of 5");let group=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA full cutoff journey")).firstMatch;XCTAssertTrue(group.waitForExistence(timeout:15),app.debugDescription);group.tap();let msg=app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch;XCTAssertTrue(msg.waitForExistence(timeout:12),app.debugDescription);type(msg,"QA106");XCTAssertEqual(msg.value as? String,"QA106");let keyboard=app.keyboards.firstMatch,send=app.buttons["Send"];XCTAssertTrue(keyboard.waitForExistence(timeout:10));print("QA_NATIVE106_GEOMETRY keyboard=\(keyboard.frame) message=\(msg.frame) send=\(send.frame) hittable=\(send.isHittable) app=\(app.frame)\n"+app.debugDescription);XCTAssertTrue(msg.isHittable);XCTAssertTrue(send.isHittable);XCTAssertLessThanOrEqual(msg.frame.maxY,keyboard.frame.minY+1);XCTAssertLessThanOrEqual(send.frame.maxY,keyboard.frame.minY+1);let geometry=XCTAttachment(screenshot:app.screenshot());geometry.name="native106-fixed-chat-keyboard-physical-send";geometry.lifetime = .keepAlways;add(geometry);send.tap();XCTAssertTrue(app.staticTexts["QA106"].waitForExistence(timeout:15),app.debugDescription);let sent=XCTAttachment(screenshot:app.screenshot());sent.name="native106-fixed-chat-actual-send";sent.lifetime = .keepAlways;add(sent);print("QA_NATIVE106_ACTUAL_SEND_CONFIRMED")
 }
}
